import yaml,glob,os
items={}
for f in glob.glob('*.yaml'):
    d=yaml.safe_load(open(f)); items[d['id']]=d
def kids(p): return sorted([i for i,d in items.items() if d.get('metadata',{}).get('parent')==p])
def show(i,ind=0):
    d=items[i]
    print(' '*ind+f\"{i} [{d.get('status')}] {d.get('title')}\")
    for k in kids(i): show(k,ind+2)
roots=[i for i,d in items.items() if not d.get('metadata',{}).get('parent')]
for r in sorted(roots): show(r)
" 2>&1 | head -120

